 async function clearEditorRecovery(){clearTimeout(recoveryTimer);editorRecovery=null;try{await itemRecoveryRequest('delete');}catch(error){console.warn('Item recovery clear failed',error);}}
 async function loadEditorRecovery(){try{return await itemRecoveryRequest('get');}catch(error){console.warn('Item recovery load failed',error);return null;}}
 function itemTypeFromDetection(label){const map={refrigerator:'Fridge',tv:'Television',couch:'Sofa / couch','dining table':'Dining table','hair drier':'Hair dryer',mouse:'Computer mouse'};const name=map[label]||String(label||'').replace(/\b\w/g,c=>c.toUpperCase());const found=HomeScanCatalog.find(name);return {name,category:found?.category||'Other'};}
 function isIOSDevice(){return /iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);}
 function labelLocationHint(it){const name=(it.name||'').toLowerCase();if(name.includes('fridge')||name.includes('refrigerator')||name.includes('freezer'))return 'For a fridge or freezer, the product label is often inside on a side wall, around the door frame, behind a drawer, or on the rear. Photograph the whole label square-on.';if((it.category||'')==='Appliances')return 'Look for the rating/product label on the back, side, underside, door frame or inside the appliance. Photograph the whole label square-on.';if((it.category||'')==='Electronics')return 'Look on the back, underside, stand, battery area or original product label. Photograph the whole label square-on.';return 'If the item has a maker or product label, photograph it square-on. HomeScan can suggest details from the printed label. If there is no label, skip this step.';}
